from datetime import date
from typing import List, Dict, Tuple

class Loyalty:
    def __init__(self) -> None:
        # Store purchases as {customer: [(amount, purchase_date, points), ...]}
        self.purchases: Dict[str, List[Tuple[float, date, int]]] = {}
        # Store redemptions as {customer: [(points, redemption_date), ...]}
        self.redemptions: Dict[str, List[Tuple[int, date]]] = {}

    def purchase(self, customer: str, amount: float, day: date) -> int:
        if amount <= 0:
            raise ValueError("Purchase amount must be greater than zero")

        # Calculate points: 1 point for every full 10.00 spent
        points = int(amount // 10.0)

        # Store the purchase
        if customer not in self.purchases:
            self.purchases[customer] = []
        self.purchases[customer].append((amount, day, points))

        return points

    def balance(self, customer: str, day: date) -> int:
        # Get all purchases for this customer
        customer_purchases = self.purchases.get(customer, [])

        # Calculate total points from purchases that are at least 14 days old
        available_points = 0
        for amount, purchase_date, points in customer_purchases:
            # Check if purchase is at least 14 days old
            days_diff = (day - purchase_date).days
            if days_diff >= 14:
                available_points += points

        # Subtract points that have been redeemed on or before this day
        customer_redemptions = self.redemptions.get(customer, [])
        for redeemed_points, redemption_date in customer_redemptions:
            if redemption_date <= day:
                available_points -= redeemed_points

        return max(0, available_points)

    def redeem(self, customer: str, points: int, day: date) -> None:
        current_balance = self.balance(customer, day)
        if points > current_balance:
            raise ValueError("Not enough points available for redemption")

        # Record the redemption
        if customer not in self.redemptions:
            self.redemptions[customer] = []
        self.redemptions[customer].append((points, day))
